package com.slime;
import android.app.Activity; import android.graphics.Color; import android.os.Bundle; import android.widget.*;
public class HistoryActivity extends Activity { @Override protected void onCreate(Bundle b){ super.onCreate(b); LinearLayout lay=new LinearLayout(this); lay.setOrientation(LinearLayout.VERTICAL); lay.setBackgroundColor(Color.WHITE); lay.setPadding(20,20,20,20); ScrollView sv=new ScrollView(this); LinearLayout inner=new LinearLayout(this); inner.setOrientation(LinearLayout.VERTICAL); MemoryManager mem=new MemoryManager(this); try{ org.json.JSONArray arr=mem.loadChats(); for(int i=0;i<arr.length();i++){ org.json.JSONObject o=arr.getJSONObject(i); TextView tv=new TextView(this); tv.setText("U: "+o.optString("u")+"\nS: "+o.optString("s")+"\n---"); tv.setTextSize(12f); tv.setPadding(0,10,0,10); inner.addView(tv); } }catch(Exception e){} sv.addView(inner); lay.addView(sv); setContentView(lay); } }
